import{a as e,i as t,s as n,t as r}from"./app-CchzzT6L.js";var i=JSON.parse(`{"path":"/AI/LLM%20Gag/real-world-ep3.html","title":"","lang":"en-US","frontmatter":{},"git":{"updatedTime":1749378724000,"contributors":[{"name":"hifat","username":"hifat","email":"logmanxsa@gmail.com","commits":1,"url":"https://github.com/hifat"}],"changelog":[{"hash":"12e48b94e378386433cc3f7be77fabe628f721c0","time":1749378724000,"email":"logmanxsa@gmail.com","author":"hifat","message":"add llm gag content"}]},"filePathRelative":"AI/LLM Gag/real-world-ep3.md"}`),a={name:`real-world-ep3.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<p>โห เพื่อน... คำว่า “อยากเจ็บ” มึงพูดได้กินใจมาก กูจะจัดเครื่องที่เจ็บแบบสมจริง ให้มึงได้ลืมหน้าเธอไปชั่วคราวเลย!</p><hr><h2 id="เครื่องที่กูแนะนําให้ลุย-—-active-บน-hackthebox" tabindex="-1"><a class="header-anchor" href="#เครื่องที่กูแนะนําให้ลุย-—-active-บน-hackthebox"><span>เครื่องที่กูแนะนำให้ลุย — <strong>Active</strong> (บน HackTheBox)</span></a></h2><h3 id="ทําไมต้อง-active" tabindex="-1"><a class="header-anchor" href="#ทําไมต้อง-active"><span>ทำไมต้อง “Active”?</span></a></h3><ul><li>เป็น <strong>real-world style Windows AD environment</strong> ที่จำลอง Domain Controller จริง ๆ</li><li>มี <strong>ช่องโหว่แบบครบสูตร</strong> ตั้งแต่ SMB, LDAP, Kerberos, Lateral Movement</li><li>เครื่องนี้ถ้าลงลึกได้ จะสอนมึงเรื่องความซับซ้อนขององค์กรใหญ่ ๆ จริง ๆ</li><li>พวกมือโปร OSCP ชอบฝึกกับเครื่องนี้ก่อนลุยสนามจริง</li><li>เจ็บแบบสมจริงแต่ไม่เจ็บจนเลิกเล่น!</li></ul><hr><h2 id="แผนลุย-active-เครื่องนี้" tabindex="-1"><a class="header-anchor" href="#แผนลุย-active-เครื่องนี้"><span>แผนลุย Active เครื่องนี้</span></a></h2><ol><li><p><strong>Recon:</strong></p><ul><li><code>nmap -sC -sV -p- &lt;IP&gt;</code></li><li><code>enum4linux -a &lt;IP&gt;</code></li><li>เช็ค SMB shares และ users</li></ul></li><li><p><strong>Enumeration:</strong></p><ul><li>ใช้ BloodHound หา privilege escalation path</li><li>รัน <code>rpcclient</code> และ <code>smbclient</code> ส่องช่องโหว่</li></ul></li><li><p><strong>Exploitation:</strong></p><ul><li>ใช้ credential ที่ได้ลองผ่าน <code>impacket</code> tools</li><li>ลอง Pass-the-Hash หรือ Pass-the-Ticket</li></ul></li><li><p><strong>Privilege Escalation และ Lateral Movement:</strong></p><ul><li>หาเครื่องอื่นใน domain</li><li>ขยายสิทธิ์โดยใช้เครื่องมือและสคริปต์ต่าง ๆ</li></ul></li></ol><hr><h2 id="ขอแค่บอกกู-ip-เครื่องนี้-หรือบอกกูว่า-พร้อม" tabindex="-1"><a class="header-anchor" href="#ขอแค่บอกกู-ip-เครื่องนี้-หรือบอกกูว่า-พร้อม"><span>ขอแค่บอกกู IP เครื่องนี้ หรือบอกกูว่า &quot;พร้อม&quot;</span></a></h2><p>กูจะจัดชุดคำสั่ง ตัวอย่าง payload และวิธีเจาะทีละขั้นให้มึงแบบเต็มแม็กซ์!</p><hr><p>เพื่อน… ถึงจะเจ็บ แต่สู้ให้สุด! เจ็บวันนี้ เพื่อแข็งแกร่งวันหน้า 🔥 บอกกูเลย “พร้อม” หรือ “เอา IP มา” เดี๋ยวลุย!</p>`,13)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};